package main

// Knowledge v2 (plan K2): the v4 capability registry (core/capabilities/**) and the generated API docs
// (wasm/docs/**, with the Nano console's own CLI/SDK/curl snippets) embedded gzipped next to mcp_matrix.json.
// Both are GENERATED by scripts/gen_mcp_matrix.py; never edit them by hand. They are decompressed lazily on
// the first call that needs them, so `initialize` stays fast.

import (
	"bytes"
	"compress/gzip"
	_ "embed"
	"encoding/json"
	"fmt"
	"io"
	"regexp"
	"sort"
	"strings"
	"sync"
)

//go:embed mcp_caps.json.gz
var mcpCapsGz []byte

//go:embed mcp_docs.json.gz
var mcpDocsGz []byte

type mcpCapability struct {
	ID          string            `json:"id"`
	Title       string            `json:"title"`
	Level       map[string]string `json:"level"`
	Tier        string            `json:"tier,omitempty"`
	Mesh        bool              `json:"mesh,omitempty"`
	Limitations []string          `json:"limitations"`
	Tests       []string          `json:"tests"`
}

type mcpCapsIndex struct {
	Schema int `json:"schema"`
	Clouds map[string]map[string]struct {
		File         string          `json:"file"`
		Capabilities []mcpCapability `json:"capabilities"`
	} `json:"clouds"`
}

type mcpDocOp struct {
	Name    string            `json:"n"`
	Method  string            `json:"m"`
	Path    string            `json:"u"`
	Desc    string            `json:"d"`
	Aliases []string          `json:"k,omitempty"`
	Snips   map[string]string `json:"s"`
}

type mcpDocAPI struct {
	ID    string     `json:"id"`
	Title string     `json:"title"`
	Pick  []int      `json:"pick"`
	Ops   []mcpDocOp `json:"ops"`
}

type mcpDocService struct {
	Title    string      `json:"title"`
	ID       string      `json:"id"`
	Category string      `json:"category"`
	Source   string      `json:"source"`
	Ops      int         `json:"ops"`
	APIs     []mcpDocAPI `json:"apis"`
	Data     []struct {
		Name   string `json:"n"`
		URL    string `json:"u"`
		Client string `json:"c"`
	} `json:"data,omitempty"`
}

type mcpDocsIndex struct {
	Schema int                                  `json:"schema"`
	Clouds map[string]map[string]*mcpDocService `json:"clouds"`
}

var (
	mcpCapsOnce sync.Once
	mcpCapsVal  *mcpCapsIndex
	mcpCapsErr  error
	mcpDocsOnce sync.Once
	mcpDocsVal  *mcpDocsIndex
	mcpDocsErr  error
)

func gunzipJSON(name string, gz []byte, v any) error {
	zr, err := gzip.NewReader(bytes.NewReader(gz))
	if err != nil {
		return fmt.Errorf("embedded %s is invalid (regenerate with scripts/gen_mcp_matrix.py): %w", name, err)
	}
	b, err := io.ReadAll(zr)
	if err != nil {
		return fmt.Errorf("embedded %s is invalid: %w", name, err)
	}
	if err := json.Unmarshal(b, v); err != nil {
		return fmt.Errorf("embedded %s is invalid: %w", name, err)
	}
	return nil
}

func loadMCPCaps() (*mcpCapsIndex, error) {
	mcpCapsOnce.Do(func() {
		var c mcpCapsIndex
		if mcpCapsErr = gunzipJSON("mcp_caps.json.gz", mcpCapsGz, &c); mcpCapsErr == nil {
			if c.Schema != mcpMatrixSchema {
				mcpCapsErr = fmt.Errorf("embedded mcp_caps.json.gz has schema %d; this binary understands %d", c.Schema, mcpMatrixSchema)
			} else {
				mcpCapsVal = &c
			}
		}
	})
	return mcpCapsVal, mcpCapsErr
}

func loadMCPDocs() (*mcpDocsIndex, error) {
	mcpDocsOnce.Do(func() {
		var d mcpDocsIndex
		if mcpDocsErr = gunzipJSON("mcp_docs.json.gz", mcpDocsGz, &d); mcpDocsErr == nil {
			if d.Schema != mcpMatrixSchema {
				mcpDocsErr = fmt.Errorf("embedded mcp_docs.json.gz has schema %d; this binary understands %d", d.Schema, mcpMatrixSchema)
			} else {
				mcpDocsVal = &d
			}
		}
	})
	return mcpDocsVal, mcpDocsErr
}

// ── vyomi_capability ─────────────────────────────────────────────────────────

const capabilityMaxResults = 20

var levelRank = map[string]int{"full": 3, "limited": 2, "config_only": 1, "not_simulated": 0}

var capWordSplit = regexp.MustCompile(`[^a-z0-9]+`)

// capMatch ranks a capability against a query: 4 exact id, 3 id prefix, 2 exact title, 1 all words, 0 no match.
// Ids are matched with and without their cloud prefix ("aks.cluster" matches azure.aks.cluster.crud).
func capMatch(cloud string, c *mcpCapability, q string, words []string) int {
	id := strings.ToLower(c.ID)
	short := strings.TrimPrefix(id, cloud+".")
	switch {
	case q == id || q == short:
		return 4
	case strings.HasPrefix(id, q) || strings.HasPrefix(short, q):
		return 3
	case q == strings.ToLower(c.Title):
		return 2
	}
	if len(words) == 0 {
		return 0
	}
	hay := map[string]bool{}
	for _, w := range capWordSplit.Split(id+" "+strings.ToLower(c.Title), -1) {
		if w != "" {
			hay[w] = true
		}
	}
	for _, w := range words {
		if hay[w] {
			continue
		}
		// plural / stem tolerance: "buckets" ~ "bucket", "versions" ~ "versioning"
		found := false
		for h := range hay {
			if len(w) >= 4 && (strings.HasPrefix(h, w) || strings.HasPrefix(w, h) && len(h) >= 4) {
				found = true
				break
			}
		}
		if !found {
			return 0
		}
	}
	return 1
}

func (s *mcpServer) toolCapability(raw json.RawMessage) (any, error) {
	var a struct {
		Query string `json:"query"`
		Cloud string `json:"cloud"`
	}
	if err := decodeArgs(raw, &a); err != nil {
		return nil, err
	}
	q := strings.ToLower(strings.TrimSpace(a.Query))
	if q == "" {
		return nil, fmt.Errorf("query is required: a capability id prefix (e.g. aks.cluster, s3.bucket) or words from its title (e.g. bucket versioning)")
	}
	clouds := mcpClouds
	if a.Cloud != "" {
		if !validCloud(a.Cloud) {
			return nil, fmt.Errorf("unknown cloud %q (want aws, gcp or azure)", a.Cloud)
		}
		clouds = []string{a.Cloud}
	}
	idx, err := loadMCPCaps()
	if err != nil {
		return nil, err
	}
	var words []string
	for _, w := range capWordSplit.Split(q, -1) {
		if w != "" {
			words = append(words, w)
		}
	}
	type hit struct {
		rank         int
		cloud, svc   string
		c            *mcpCapability
		nano, offlne int
	}
	var hits []hit
	for _, cloud := range clouds {
		for svc, entry := range idx.Clouds[cloud] {
			for i := range entry.Capabilities {
				c := &entry.Capabilities[i]
				if r := capMatch(cloud, c, q, words); r > 0 {
					hits = append(hits, hit{r, cloud, svc, c, levelRank[c.Level["nano"]], levelRank[c.Level["offline"]]})
				}
			}
		}
	}
	sort.Slice(hits, func(i, j int) bool {
		x, y := hits[i], hits[j]
		if x.rank != y.rank {
			return x.rank > y.rank
		}
		if x.nano != y.nano {
			return x.nano > y.nano // full before limited
		}
		if x.offlne != y.offlne {
			return x.offlne > y.offlne
		}
		return x.c.ID < y.c.ID
	})
	total := len(hits)
	if len(hits) > capabilityMaxResults {
		hits = hits[:capabilityMaxResults]
	}
	matches := make([]map[string]any, 0, len(hits))
	for _, h := range hits {
		m := map[string]any{
			"id": h.c.ID, "title": h.c.Title, "cloud": h.cloud, "service": h.svc,
			"level":       map[string]string{"nano": h.c.Level["nano"], "offline": h.c.Level["offline"]},
			"limitations": nonNil(h.c.Limitations), "tests": nonNil(h.c.Tests),
		}
		if h.c.Tier != "" {
			m["tier"] = h.c.Tier
		}
		if h.c.Mesh {
			m["mesh"] = true
			m["needs"] = "a Pro/Max mesh (local or Codespace): not available on Nano or the offline appliance"
		} else if h.c.Tier == "pro" {
			m["needs"] = "a Pro (or higher) licence"
		}
		matches = append(matches, m)
	}
	out := map[string]any{
		"query": a.Query, "matches": matches, "total_matches": total, "truncated": total > len(matches),
		"level_legend": map[string]string{
			"full":          "behaves like the cloud for this feature",
			"limited":       "works, with the limitations listed",
			"config_only":   "configuration is stored and shown, the behaviour is not simulated",
			"not_simulated": "not available",
			"nano":          "the browser tab (Nano), reached through the local tunnel or the cloud relay",
			"offline":       "the Docker appliance / mesh",
		},
	}
	if total == 0 {
		out["hint"] = "No capability matched. Try an id prefix (s3.bucket, azure.aks, gcp.pubsub) or fewer words; vyomi_services lists the services."
	}
	return out, nil
}

func nonNil(xs []string) []string {
	if xs == nil {
		return []string{}
	}
	return xs
}

// ── vyomi_snippet ────────────────────────────────────────────────────────────

var snippetLangs = []string{"cli", "python", "javascript", "curl"}

// docService finds a docs service by file stem, doc id, registry id (through capability_service) or title.
func (s *mcpServer) docService(docs *mcpDocsIndex, cloud, name string) (string, *mcpDocService, error) {
	svcs := docs.Clouds[cloud]
	n := strings.ToLower(strings.TrimSpace(name))
	if d, ok := svcs[n]; ok {
		return n, d, nil
	}
	cands := []string{}
	if ms := s.matrix.service(cloud, n); ms != nil && ms.CapabilityService != "" {
		cands = append(cands, strings.SplitN(ms.CapabilityService, "#", 2)[0])
	}
	cands = append(cands, "security_"+n, strings.ReplaceAll(n, "_", "-"), strings.ReplaceAll(n, "-", ""))
	for _, c := range cands {
		if d, ok := svcs[c]; ok {
			return c, d, nil
		}
	}
	for _, stem := range sortedKeys(svcs) {
		d := svcs[stem]
		if strings.ToLower(d.ID) == n || strings.ToLower(d.Title) == n {
			return stem, d, nil
		}
	}
	var sub []string
	for _, stem := range sortedKeys(svcs) {
		if strings.Contains(stem, n) || strings.Contains(strings.ToLower(svcs[stem].Title), n) {
			sub = append(sub, stem)
		}
	}
	if len(sub) == 1 {
		return sub[0], svcs[sub[0]], nil
	}
	if len(sub) > 1 {
		return "", nil, fmt.Errorf("service %q is ambiguous for %s: %s", name, cloud, strings.Join(sub, ", "))
	}
	return "", nil, fmt.Errorf("no %s service %q in the API docs; have %s", cloud, name, strings.Join(sortedKeys(svcs), ", "))
}

func opMatches(o *mcpDocOp, want string) bool {
	w := strings.ToLower(want)
	n := strings.ToLower(o.Name)
	if n == w || strings.HasSuffix(n, "."+w) {
		return true
	}
	for _, k := range o.Aliases {
		if k == w {
			return true
		}
	}
	return false
}

// pickOp returns the requested op, or the default: the first of the registry's known actions for the service
// (CreateBucket, PutObject...), then the console's representative ops (pickOps), then the first op with a
// snippet in lang.
func (s *mcpServer) pickOp(cloud string, svc *mcpDocService, regID, op, lang string) (*mcpDocAPI, *mcpDocOp, error) {
	if op != "" {
		for ai := range svc.APIs {
			for oi := range svc.APIs[ai].Ops {
				if o := &svc.APIs[ai].Ops[oi]; opMatches(o, op) {
					if _, ok := o.Snips[lang]; !ok {
						return nil, nil, fmt.Errorf("%s has no %s snippet; have %s", o.Name, lang, strings.Join(sortedKeys(o.Snips), ", "))
					}
					return &svc.APIs[ai], o, nil
				}
			}
		}
		var names []string
		for _, a := range svc.APIs {
			for _, o := range a.Ops {
				if len(names) < 40 {
					names = append(names, o.Name)
				}
			}
		}
		return nil, nil, fmt.Errorf("no operation %q in %s; some of the %d operations: %s", op, svc.Title, svc.Ops, strings.Join(names, ", "))
	}
	if ms := s.matrix.service(cloud, regID); ms != nil {
		for _, act := range ms.Actions {
			for ai := range svc.APIs {
				for oi := range svc.APIs[ai].Ops {
					if o := &svc.APIs[ai].Ops[oi]; strings.EqualFold(o.Name, act) && o.Snips[lang] != "" {
						return &svc.APIs[ai], o, nil
					}
				}
			}
		}
	}
	for ai := range svc.APIs {
		for _, p := range svc.APIs[ai].Pick {
			if o := &svc.APIs[ai].Ops[p]; o.Snips[lang] != "" {
				return &svc.APIs[ai], o, nil
			}
		}
	}
	for ai := range svc.APIs {
		for oi := range svc.APIs[ai].Ops {
			if o := &svc.APIs[ai].Ops[oi]; o.Snips[lang] != "" {
				return &svc.APIs[ai], o, nil
			}
		}
	}
	return nil, nil, fmt.Errorf("%s has no %s snippets; try another lang (%s)", svc.Title, lang, strings.Join(snippetLangs, ", "))
}

func (s *mcpServer) toolSnippet(raw json.RawMessage) (any, error) {
	var a struct {
		Cloud   string `json:"cloud"`
		Service string `json:"service"`
		Op      string `json:"op"`
		Lang    string `json:"lang"`
		Home    string `json:"home"`
	}
	if err := decodeArgs(raw, &a); err != nil {
		return nil, err
	}
	if !validCloud(a.Cloud) {
		return nil, fmt.Errorf("cloud is required: aws, gcp or azure")
	}
	if a.Service == "" {
		return nil, fmt.Errorf("service is required (e.g. s3, pubsub, storage); vyomi_services lists them")
	}
	if a.Lang == "" {
		a.Lang = "cli"
	}
	if !contains(snippetLangs, a.Lang) {
		return nil, fmt.Errorf("lang must be one of %s", strings.Join(snippetLangs, ", "))
	}
	docs, err := loadMCPDocs()
	if err != nil {
		return nil, err
	}
	stem, svc, err := s.docService(docs, a.Cloud, a.Service)
	if err != nil {
		return nil, err
	}
	api, op, err := s.pickOp(a.Cloud, svc, strings.ToLower(a.Service), a.Op, a.Lang)
	if err != nil {
		return nil, err
	}
	home, err := s.resolveHome(a.Home)
	if err != nil {
		return nil, err
	}
	t := home.target
	out := map[string]any{
		"cloud": a.Cloud, "service": stem, "title": svc.Title, "api": api.Title,
		"op": op.Name, "method": op.Method, "path": op.Path, "description": op.Desc,
		"lang": a.Lang, "home": home.ID, "endpoint": t.simURL(),
		"snippet":         t.renderSnippet(op.Snips[a.Lang]),
		"available_langs": sortedKeys(op.Snips),
		"source":          svc.Source,
		"note":            "Generated from the API docs the Nano console shows (only operations that really answer). Placeholder values (my-bucket, my-rg) are examples.",
	}
	if a.Op == "" {
		out["picked"] = "default operation for this service; pass op to choose another (" + fmt.Sprint(svc.Ops) + " available)"
	}
	if home.Warning != "" {
		out["warning"] = home.Warning
	}
	return out, nil
}

// renderSnippet substitutes only the endpoint placeholder: snippets are third-party code, so the other
// render() tokens ({host}, {account}...) must not be touched if they ever appear in one.
func (t mcpTarget) renderSnippet(s string) string {
	return strings.ReplaceAll(s, "{sim}", t.simURL())
}
